def shortest_path(graph, source, target):
    # Initialize the path and distance
    def init_path_and_distance(n):
        # 0 for source, infinity for other nodes, and None for path
        return {
            'path': [n,],  # Represent the path with the node itself
            'distance': 0 if n == source else float('inf'),  # Distance from source
            'visited': False  # Indicates if the node has been visited
        }

    distances = {node: init_path_and_distance(node) for node in graph}
    distances[source]['distance'] = 0

    while any(not d['visited'] for d in distances.values()):
        # Select the unvisited node with the smallest known distance
        current_node = next(node for node, d in distances.items() if not d['visited'] and (d['distance'] == 0 or d['distance'] == min(distances[node]['distance'] for node in distances))
        if current_node == target:
            break
        distances[current_node]['visited'] = True

        for neighbor, weight in graph.get(current_node, []):
            if not distances[neighbor]['visited']:
                new_distance = distances[current_node]['distance'] + weight
                if new_distance < distances[neighbor]['distance']:
                    distances[neighbor]['distance'] = new_distance
                    distances[neighbor]['path'] = distances[current_node]['path'] + [neighbor]

    # If target is not reachable
    if distances[target]['distance'] == float('inf'):
        return float('inf'), None
    else:
        return distances[target]['distance'], distances[target]['path']

